import { Component } from '@angular/core';
import { Form, GenericFormComponent } from "../../../shared/generic-form/generic-form.component";
import { JuzgadoService } from '../../../controllers/juzgado.service';
import { ActivatedRoute } from '@angular/router';
import { Juzgado } from '../../../models/juzgados.model';
import { UtilsService } from '../../../services/utils.service';

const FORM_DEF:Form=[
  {
    key:'ciudad_id',
    label:'Ciudad:',
    apiUrl:'api/ciudades',
    keyList:'id',
    keyDetalle:'nombre',
    style:{
      div:'col p-3'
    }
  },
  {
    key:'nombre',
    label:'Nombre',
    type:'text',
    style:{
      div:'col p-3'
    }
  }
]

@Component({
    selector: 'app-form-juzgados',
    imports: [
        GenericFormComponent
    ],
    templateUrl: './form-juzgados.component.html',
    styleUrl: './form-juzgados.component.css'
})
export class FormJuzgadosComponent {
  form= FORM_DEF
  edit?:Juzgado
  constructor(
    public juzgadoController:JuzgadoService,
    private route: ActivatedRoute,
    private utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('juzgado_id'))
      if(id){
        this.edit=await this.juzgadoController.find(id)
      }
    })
  }
}
